import { bootstrapApplication } from '@angular/platform-browser';
import { provideRouter } from '@angular/router';
import { provideHttpClient, withInterceptors } from '@angular/common/http';
import { AppComponent } from './app/app.component';
import { routes } from './app/app.routes';
import { authInterceptor } from './app/services/auth.interceptor';

// Bootstrapping (Q80-81): az alkalmazás indítása standalone módon, NgModule nélkül
bootstrapApplication(AppComponent, {
  providers: [
    provideRouter(routes),                              // Router beállítása
    provideHttpClient(withInterceptors([authInterceptor])), // HttpClient + interceptor
  ],
}).catch(err => console.error(err));

import { Component } from '@angular/core';
import { RouterOutlet, RouterLink, RouterLinkActive } from '@angular/router';

// Root standalone komponens (Q39-40) - az app belépési nézete
@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet, RouterLink, RouterLinkActive],
  template: `
    <h1>Angular Mini Demo</h1>
    <nav>
      <!-- routerLink (Q45): deklaratív navigáció -->
      <a routerLink="/tasks" routerLinkActive="active">Feladatok</a> |
      <a routerLink="/users" routerLinkActive="active">Felhasználók</a>
    </nav>
    <hr />
    <!-- router-outlet (Q46): ide renderelődik a matched komponens -->
    <router-outlet></router-outlet>
  `,
  styles: [`
    nav a { text-decoration: none; margin: 0 4px; }
    nav a.active { font-weight: bold; color: #1976d2; }
    h1 { font-family: sans-serif; }
  `],
})
export class AppComponent {}

import { Routes } from '@angular/router';
import { TasksComponent } from './components/tasks.component';
import { authGuard } from './guards/auth.guard';

// Route konfiguráció (Q43-44)
export const routes: Routes = [
  { path: '', redirectTo: 'tasks', pathMatch: 'full' },
  { path: 'tasks', component: TasksComponent },
  {
    path: 'users',
    // Lazy loading (Q49): a komponens csak navigációkor töltődik be
    loadComponent: () =>
      import('./components/users.component').then(m => m.UsersComponent),
    canActivate: [authGuard],   // route guard (Q47)
  },
  { path: '**', redirectTo: 'tasks' },  // wildcard route (Q50)
];

// TypeScript interfész (Q3) - statikus típusdefiníció
export interface Task {
  id: number;
  title: string;
  done: boolean;
  priority: 'low' | 'high';   // union típus
}

export interface User {
  id: number;
  name: string;
  email: string;
}

import { Injectable, signal, computed } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Task } from '../models/task.model';

// @Injectable + providedIn:'root' (Q31-34) => alkalmazás-szintű singleton, tree-shakeable
@Injectable({ providedIn: 'root' })
export class TaskService {
  // BehaviorSubject (Q56): van kezdőérték, az utolsó értéket adja új feliratkozóknak
  private tasksSubject = new BehaviorSubject<Task[]>([
    { id: 1, title: 'Angular tanulás',   done: false, priority: 'high' },
    { id: 2, title: 'RxJS gyakorlás',     done: true,  priority: 'low' },
    { id: 3, title: 'Interview felkészülés', done: false, priority: 'high' },
  ]);

  // Observable (Q51-52): aszinkron adatfolyam, a komponens async pipe-pal fogyasztja
  tasks$: Observable<Task[]> = this.tasksSubject.asObservable();

  // Signal (Q76): reaktív primitív, finomabb change detection Zone.js nélkül
  counter = signal(0);
  doubleCounter = computed(() => this.counter() * 2); // computed signal

  addTask(title: string): void {
    const current = this.tasksSubject.value;
    const newTask: Task = { id: Date.now(), title, done: false, priority: 'low' };
    this.tasksSubject.next([...current, newTask]); // immutable frissítés
  }

  toggle(id: number): void {
    const updated = this.tasksSubject.value.map(t =>
      t.id === id ? { ...t, done: !t.done } : t
    );
    this.tasksSubject.next(updated);
  }

  increment(): void {
    this.counter.update(v => v + 1);
  }
}

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, catchError, of } from 'rxjs';
import { User } from '../models/task.model';

@Injectable({ providedIn: 'root' })
export class UserService {
  // inject() függvény (Q91): DI constructor nélkül
  private http = inject(HttpClient);

  // HttpClient (Q59): GET kérés, Observable-t ad vissza
  getUsers(): Observable<User[]> {
    return this.http.get<User[]>('https://jsonplaceholder.typicode.com/users').pipe(
      // catchError (Q60): HTTP hibakezelés
      catchError(() => of([{ id: 0, name: 'Hiba történt', email: '-' }]))
    );
  }
}

import { HttpInterceptorFn } from '@angular/common/http';

// HTTP interceptor (Q61-62): kimenő kérések globális elfogása
// Pl. auth token hozzáadása minden kéréshez (a request klónozásával)
export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const cloned = req.clone({
    setHeaders: { Authorization: 'Bearer demo-token' },
  });
  return next(cloned);
};

import { Directive, HostListener, HostBinding, ElementRef, Renderer2, inject } from '@angular/core';

// Egyéni ATTRIBÚTUM direktíva (Q17-18, Q23): megjelenést/viselkedést módosít
@Directive({
  selector: '[appHighlight]',
  standalone: true,
})
export class HighlightDirective {
  private el = inject(ElementRef);      // ElementRef (Q85): natív DOM elem elérése
  private renderer = inject(Renderer2); // Renderer2: biztonságos DOM manipuláció

  // @HostBinding (Q24): a host elem property-jét köti
  @HostBinding('style.cursor') cursor = 'pointer';

  // @HostListener (Q24): host elem eseményeire figyel
  @HostListener('mouseenter') onEnter(): void {
    this.renderer.setStyle(this.el.nativeElement, 'backgroundColor', '#fff3cd');
  }

  @HostListener('mouseleave') onLeave(): void {
    this.renderer.removeStyle(this.el.nativeElement, 'backgroundColor');
  }
}

import { Pipe, PipeTransform } from '@angular/core';

// Egyéni pipe (Q68, Q71): adat transzformáció megjelenítéshez
// Pure pipe (Q70): csak input referencia változásra fut (alap, gyors)
@Pipe({
  name: 'capitalize',
  standalone: true,
})
export class CapitalizePipe implements PipeTransform {
  transform(value: string): string {
    if (!value) return '';
    return value.charAt(0).toUpperCase() + value.slice(1);
  }
}

import { CanActivateFn } from '@angular/router';

// Route guard (Q47) - funkcionális CanActivate (modern szintaxis)
// Eldönti, engedélyezett-e a navigáció az adott route-ra
export const authGuard: CanActivateFn = () => {
  const isLoggedIn = true; // valós appban: AuthService.isLoggedIn()
  return isLoggedIn;
};

import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { Task } from '../models/task.model';
import { HighlightDirective } from '../directives/highlight.directive';
import { CapitalizePipe } from '../pipes/capitalize.pipe';

// Standalone gyerek komponens (Q6, Q40) - "dumb/presentational" komponens (Q96)
@Component({
  selector: 'app-task-item',
  standalone: true,
  imports: [HighlightDirective, CapitalizePipe],
  // OnPush change detection (Q74-75): csak @Input referencia változásra fut => gyorsabb
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <li appHighlight [class.done]="task.done">
      <!-- Property binding (Q14) -->
      <input type="checkbox" [checked]="task.done"
             (change)="toggle.emit(task.id)" />
      <!-- Interpoláció + egyéni pipe (Q68) -->
      {{ task.title | capitalize }}
      <small>[{{ task.priority }}]</small>
      <!-- ng-content: content projection (Q30) -->
      <ng-content></ng-content>
    </li>
  `,
  styles: [`.done { text-decoration: line-through; opacity: .6; }`],
})
export class TaskItemComponent {
  // @Input (Q25): szülő -> gyerek adatátadás
  @Input({ required: true }) task!: Task;

  // @Output (Q26): gyerek -> szülő eseménykibocsátás EventEmitter-rel
  @Output() toggle = new EventEmitter<number>();
}

import { Component, OnInit, OnDestroy, ViewChild, ElementRef, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormControl, ReactiveFormsModule, Validators } from '@angular/forms';
import { Subscription } from 'rxjs';
import { TaskService } from '../services/task.service';
import { TaskItemComponent } from './task-item.component';

// "Smart/container" komponens (Q96): állapotot és logikát kezel
@Component({
  selector: 'app-tasks',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, TaskItemComponent],
  template: `
    <h2>Feladatok</h2>

    <!-- Reactive form (Q63-66): FormControl + beépített validátor -->
    <input #titleInput [formControl]="title" placeholder="Új feladat..." />
    <button (click)="add()" [disabled]="title.invalid">Hozzáad</button>
    <!-- ngIf régi vs @if új control flow (Q19, Q93) -->
    @if (title.invalid && title.touched) {
      <span class="err">Min. 3 karakter!</span>
    }

    <!-- async pipe (Q55): auto subscribe + unsubscribe a template-ben -->
    <ul>
      @for (task of (tasks$ | async); track task.id) {   <!-- @for + track (Q20-21) -->
        <app-task-item [task]="task" (toggle)="onToggle($event)">
          <em>#{{ task.id }}</em>
        </app-task-item>
      } @empty {
        <li>Nincs feladat</li>
      }
    </ul>

    <!-- Signals (Q76): reaktív számláló, Zone.js nélkül -->
    <p>Signal számláló: {{ svc.counter() }} (dupla: {{ svc.doubleCounter() }})</p>
    <button (click)="svc.increment()">+1</button>
  `,
  styles: [`.err { color: red; margin-left: 8px; } h2 { color: #1976d2; }`],
})
export class TasksComponent implements OnInit, OnDestroy {
  svc = inject(TaskService);
  tasks$ = this.svc.tasks$;
  private sub?: Subscription;

  // FormControl validátorral (Q66)
  title = new FormControl('', [Validators.required, Validators.minLength(3)]);

  // @ViewChild (Q28): hozzáférés template elemhez
  @ViewChild('titleInput') titleInput!: ElementRef<HTMLInputElement>;

  // ngOnInit (Q9): inicializálás miután az input propertyk beálltak
  ngOnInit(): void {
    // Manuális subscribe példa -> ngOnDestroy-ban leiratkozunk (Q54)
    this.sub = this.tasks$.subscribe();
  }

  add(): void {
    if (this.title.valid) {
      this.svc.addTask(this.title.value!.trim());
      this.title.reset();
      this.titleInput.nativeElement.focus(); // ViewChild használat
    }
  }

  onToggle(id: number): void {
    this.svc.toggle(id);
  }

  // ngOnDestroy (Q10): takarítás, memory leak megelőzés
  ngOnDestroy(): void {
    this.sub?.unsubscribe();
  }
}

import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { UserService } from '../services/user.service';

// Ez a komponens LAZY LOADING-gal töltődik be (Q49) - lásd app.routes.ts
@Component({
  selector: 'app-users',
  standalone: true,
  imports: [CommonModule],
  template: `
    <h2>Felhasználók (HTTP)</h2>
    <!-- async pipe (Q55) az Observable-höz, @for + @empty control flow -->
    <ul>
      @for (user of (users$ | async); track user.id) {
        <li>{{ user.name }} — <small>{{ user.email }}</small></li>
      } @empty {
        <li>Betöltés...</li>
      }
    </ul>
  `,
  styles: [`h2 { color: #1976d2; }`],
})
export class UsersComponent {
  private userService = inject(UserService);
  users$ = this.userService.getUsers(); // Observable a HTTP GET-ből
}
